Clase Contador
    Publico Definir valor Como Entero;
FinClase

Proceso EjecutarAlias
    Definir n Como Entero;
    Definir i Como Entero;
    Definir a Como Contador;
    Definir b Como Contador;
    Leer n;
    a <- Nuevo Contador();
    a.valor <- 0;
    b <- a;
    Para i <- 1 Hasta n Con Paso 1 Hacer
        b.valor <- b.valor + 1;
    FinPara
    Escribir a.valor;
FinProceso
